using System;using System.Linq;using Mono.Cecil;
class Program {static void Main(string[] a){var asm=AssemblyDefinition.ReadAssembly(a[0]);foreach(var t in asm.MainModule.Types.Where(t=>a.Skip(1).Any(n=>t.FullName==n))){Console.WriteLine("TYPE "+t.FullName);foreach(var f in t.Fields) Console.WriteLine("FIELD "+f.FullName);foreach(var m in t.Methods){if(m.Name.Contains("Skin")||m.Name.Contains("InitGUI")||m.Name.Contains("GetMaterialProperties")||m.Name=="get_label"||m.Name=="PropertiesGUI"||m.Name=="OnInspectorGUI"||m.Name=="OnEnable"||m.Name=="HasMultipleMixedShaderValues"||m.Name=="ResetGUIState"||m.Name=="InitSharedStyles"||m.Name=="GetStyle"||m.Name=="BeginGUI"||m.Name=="EndGUI"||m.Name==".cctor"||m.Name=="GetBuiltinSkin"||m.Name=="get_skin"||m.Name=="set_skin"||m.Name=="RefreshSkin"||m.Name=="RefreshSkinInternal"||m.Name=="CheckOnGUI"||m.Name=="SendEvent"||m.Name=="Show"||m.Name=="ShowUtility"||m.Name=="ShowPopup"||m.Name=="ShowModalUtility"||m.Name=="ShowWithMode"||m.Name=="get_m_Parent"||m.Name=="set_vectorValue"||m.Name=="ApplyProperty"||m.Name=="ApplyMaterialProperty"||m.Name=="GetTextureScale"||m.Name=="GetTextureOffset"||m.Name=="SetVector"||m.Name=="SetVectorImpl"||m.Name=="GetTextureScaleAndOffsetImpl") {Console.WriteLine("METHOD "+m.FullName);if(m.HasBody) foreach(var i in m.Body.Instructions) Console.WriteLine(i);}}}}}
